package hexadecimal

import (
	"errors"
	"fmt"
)

// ParseHex converts a hexadecimal string to its decimal equivalent.
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, errors.New("syntax error: empty input")
	}

	var out int64
	for _, r := range in {
		var digit int64
		switch {
		case r >= '0' && r <= '9':
			digit = int64(r - '0')
		case r >= 'a' && r <= 'f':
			digit = int64(r-'a') + 10
		case r >= 'A' && r <= 'F':
			digit = int64(r-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid character %q", r)
		}

		// Check for overflow before updating out.
		if out > (int64(1)<<62-1-digit)/16 {
			return 0, fmt.Errorf("range error: value out of range")
		}
		out = out*16 + digit
	}
	return out, nil
}

// HandleErrors calls ParseHex on each input and reports "none", "syntax",
// or "range" for the corresponding error case.
func HandleErrors(in []string) []string {
	out := make([]string, len(in))
	for i, s := range in {
		_, err := ParseHex(s)
		if err == nil {
			out[i] = "none"
		} else if err == errSyntax {
			out[i] = "syntax"
		} else {
			out[i] = "range"
		}
	}
	return out
}

